#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long size;
    long long k;
    cin >> size >> k;
    vector<long long> bed(size);
    for (int i = 0; i < size; i++) cin >> bed[i];

    long long planted = 0;
    for (long long i = 0; i < size; i++) {
        bool leftFree = i == 0 || bed[i - 1] == 0;
        bool rightFree = i == size - 1 || bed[i + 1] == 0;
        if (bed[i] == 0 && leftFree && rightFree) {
            bed[i] = 1;
            planted++;
        }
    }
    cout << (planted >= k ? "yes" : "no") << "\n";

    return 0;
}

