import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long size = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] bed = new long[(int) size];
        for (int i = 0; i < bed.length; i++) bed[i] = Long.parseLong(next());

        long planted = 0;
        for (int i = 0; i < size; i++) {
            boolean leftFree = i == 0 || bed[i - 1] == 0;
            boolean rightFree = i == size - 1 || bed[i + 1] == 0;
            if (bed[i] == 0 && leftFree && rightFree) {
                bed[i] = 1;
                planted++;
            }
        }
        System.out.println(planted >= k ? "yes" : "no");
    }
}
